	public void EveryOctetUsesCanonicalByteOrScalarLiterals( int selection, int mode ) {
		var sources = Enumerable.Range( 0, 256 ).Select( value => Encoding.ASCII.GetBytes( String.Concat( @"\A(\u{", value.ToString( "X4" ), @"})\z" ) ) ).ToArray();
		var references = sources.Select( source => Reference( source, selection, mode ) ).ToArray();
		for ( var value = 0; value < sources.Length; value++ ) {
			var subject = ( mode & 5 ) != 0 ? Encoding.UTF8.GetBytes( ( (char)value ).ToString() ) : new[] { (byte)value };
			AssertLiteral( references[value], subject, $"0:{subject.Length},0:{subject.Length}", "" );
			Compare( references[value], subject, 0, Compile( sources[value], Options( selection, mode ) ).Match( subject ), $"braced value {value}" );
		}
	}

