	[Fact]
	public void BracedLiteralsKeepCanonicalWorkAndCancellation() {
		var source = Encoding.ASCII.GetBytes( @"(\u{41}|\u{41}\u{41})+B" );
		var subject = "AAA"u8.ToArray();
		var reference = Reference( source, 2, 0 );
		AssertLiteral( reference, subject, "", "" );
		var steps = new List<int>();
		var options = Options( 2, 0 ) with { WorkObserver = steps.Add };
		Compare( reference, subject, 0, Compile( source, options ).Match( subject ), "braced work" );
		Assert.Equal( Enumerable.Range( 1, steps.Count ), steps );
		Assert.True( steps.Count > 2 );
		var limited = Compile( source, options with { MatchWorkLimit = steps.Count - 1 } ).Match( subject );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
		Assert.Null( limited.Match );
		using var cancellation = new CancellationTokenSource();
		var compiled = Compile( source, options with { WorkObserver = count => { if ( count == 2 ) { cancellation.Cancel(); } } } );
		Assert.Throws<OperationCanceledException>( () => compiled.Match( subject, 0, cancellation.Token ) );
		Assert.Throws<OperationCanceledException>( () => PcreByteCompiler.Compile( source, options, cancellation.Token ) );
	}

	[Fact]
	public void FallbackBraceKeepsCanonicalScopeAndWorkRatherThanRepeatingThePrefix() {
		var sources = new[] { Encoding.ASCII.GetBytes( @"\u{{2}B" ), Encoding.ASCII.GetBytes( @"u\{{2}B" ) };
		var references = sources.Select( source => Reference( source, 2, 0 ) ).ToArray();
		var subject = "u{{C"u8.ToArray();
		foreach ( var reference in references ) { AssertLiteral( reference, subject, "", "" ); }
		var alternate = new List<int>();
		var canonical = new List<int>();
		Compare( references[0], subject, 0, Compile( sources[0], Options( 2, 0 ) with { WorkObserver = alternate.Add } ).Match( subject ), "literal brace work" );
		Compare( references[1], subject, 0, Compile( sources[1], Options( 2, 0 ) with { WorkObserver = canonical.Add } ).Match( subject ), "canonical brace work" );
		Assert.NotEmpty( canonical );
		Assert.Equal( canonical, alternate );
	}

	[Fact]
	public void CompiledBracedLiteralsOwnSupplementarySourceAndOptionState() {
		var source = Encoding.ASCII.GetBytes( @"(?<x>\u{1f600})\k<x>" );
		var subject = "😀😀"u8.ToArray();
		var reference = Reference( source, 2, 3 );
		AssertLiteral( reference, subject, "0:8,0:4", "" );
		var options = Options( 2, 3 );
		var compiled = Compile( source, options );
		Array.Fill( source, (byte)'x' );
		typeof( PcreByteOptions ).GetProperty( "ExtraAltBsux" )?.SetValue( options, false );
		Compare( reference, subject, 0, compiled.Match( subject ), "owned supplementary source" );
	}

	[Fact]
	public void BracedLiteralsRetainSharedStructuralQuotas() {
		var patterns = new[] {
			String.Concat( String.Concat( Enumerable.Repeat( "()", 256 ) ), @"\u{41}" ),
			String.Concat( String.Concat( Enumerable.Repeat( "()", 257 ) ), @"\u{41}" ),
			String.Concat( new string( '(', 257 ), @"\u{41}", new string( ')', 257 ) ), @"\u{41}{4096}"
		};
		var references = patterns.Select( pattern => Reference( Encoding.ASCII.GetBytes( pattern ), 2, 0 ) ).ToArray();
		Compare( references[0], "A"u8.ToArray(), 0, Compile( Encoding.ASCII.GetBytes( patterns[0] ), Options( 2, 0 ) ).Match( "A"u8.ToArray() ), "braced full capture capacity" );
		var codes = new[] { PcreByteDiagnosticCode.PatternCaptureLimitExceeded, PcreByteDiagnosticCode.PatternDepthLimitExceeded, PcreByteDiagnosticCode.PatternRepeatLimitExceeded };
		for ( var index = 1; index < patterns.Length; index++ ) {
			var actual = PcreByteCompiler.Compile( Encoding.ASCII.GetBytes( patterns[index] ), Options( 2, 0 ) );
			Assert.Equal( codes[index - 1], actual.Diagnostic?.Code );
			Assert.Null( actual.Pattern );
		}
	}

	[Fact]
	public void PriorCallerProhibitionsKeepPrecedenceWithoutRelexingDecodedSlashes() {
		var sources = new[] { Encoding.ASCII.GetBytes( @"\u{41}" ), Encoding.ASCII.GetBytes( @"(*UCP)\u{41}" ), Encoding.ASCII.GetBytes( @"\u{41}\C" ) };
		var modes = new[] { 1, 0, 0 };
		var flags = new uint[] { 0x1000, 0x800, 0x100000 };
		var nativeCodes = new[] { 174, 175, 183 };
		var nativeOffsets = new[] { 0, 6, 8 };
		var offsets = new[] { 0, 6, 6 };
		var native = sources.Select( ( source, index ) => Assert.Throws<PcrePatternException>( () => Reference( source, 2, modes[index], flags[index] ) ) ).ToArray();
		for ( var index = 0; index < sources.Length; index++ ) {
			Assert.Equal( nativeCodes[index], (int)native[index].ErrorCode );
			Assert.EndsWith( $" at offset {nativeOffsets[index]}.", native[index].Message );
		}
		var options = new[] { Options( 2, 1 ) with { NeverUtf = true }, Options( 2, 0 ) with { NeverUcp = true }, Options( 2, 0 ) with { NeverBackslashC = true } };
		for ( var index = 0; index < sources.Length; index++ ) {
			var actual = PcreByteCompiler.Compile( sources[index], options[index] );
			Assert.Equal( PcreByteDiagnosticCode.InvalidSyntax, actual.Diagnostic?.Code );
			Assert.Equal( offsets[index], actual.Diagnostic?.ByteOffset );
			Assert.Contains( "disabled by the caller", actual.Diagnostic!.Message );
			Assert.Null( actual.Pattern );
		}
		var literal = Encoding.ASCII.GetBytes( @"\u{5c}C" );
		var reference = Reference( literal, 2, 0, 0x100000 );
		var subject = "\\C"u8.ToArray();
		AssertLiteral( reference, subject, "0:2", "" );
		Compare( reference, subject, 0, Compile( literal, Options( 2, 0 ) with { NeverBackslashC = true } ).Match( subject ), "braced slash is not syntax" );
	}

	[Fact]
	public void WholePatternUtfValidationStillPrecedesExtraGrammar() {
		var source = Encoding.ASCII.GetBytes( @"\u{41}" ).Concat( new byte[] { 0xFF } ).ToArray();
		foreach ( var selection in new[] { 0, 2 } ) {
			var native = Assert.Throws<PcrePatternException>( () => Reference( source, selection, 3 ) );
			Assert.Equal( -23, (int)native.ErrorCode );
			Assert.EndsWith( " at offset 6.", native.Message );
			var actual = PcreByteCompiler.Compile( source, Options( selection, 3 ) );
			Assert.Equal( PcreByteDiagnosticCode.InvalidUtf8Pattern, actual.Diagnostic?.Code );
			Assert.Equal( 6, actual.Diagnostic?.ByteOffset );
			Assert.Null( actual.Pattern );
		}
	}

	[Fact]
	public void ExtraGrammarDoesNotCreateAPatternDirective() {
		var source = "(*EXTRA_ALT_BSUX)A"u8.ToArray();
		foreach ( var selection in new[] { 0, 2 } ) {
			Assert.Throws<PcrePatternException>( () => Reference( source, selection, 0 ) );
			var actual = PcreByteCompiler.Compile( source, Options( selection, 0 ) );
			Assert.Equal( PcreByteDiagnosticCode.UnsupportedSyntax, actual.Diagnostic?.Code );
			Assert.Equal( 0, actual.Diagnostic?.ByteOffset );
			Assert.Null( actual.Pattern );
		}
	}

	private static readonly string[] OffsetBodies = [@"\u{41}", @"(\u{41})\u{42}", @"(?<=\u{41})\u{42}", @"\G(\u{41})", @"[\u{9}-\u{c}]A", @"[\u{a}]A", @"[\u{d}\u{a}]A", @"(?m)^\u{41}", @"\u{{2}", @"(?<=\u{{2})A"];
	private static PcreByteOptions Options( int selection, int mode ) {
		var options = new PcreByteOptions { AltBsux = ( selection & 1 ) != 0, Utf8 = ( mode & 1 ) != 0, Ucp = ( mode & 2 ) != 0,
			MatchInvalidUtf = ( mode & 4 ) != 0, Caseless = ( mode & 8 ) != 0, Extended = ( mode & 16 ) != 0, AltExtendedClass = ( mode & 32 ) != 0 };
		// Keep tests-only RED executable before the new caller property exists.
		if ( ( selection & 2 ) != 0 ) { typeof( PcreByteOptions ).GetProperty( "ExtraAltBsux" )?.SetValue( options, true ); }
		return options;
	}
	private static PcreRegex8Bit Reference( byte[] source, int selection, int mode, uint flags = 0 ) => new(
		source, Encoding.UTF8, new PcreRegexSettings {
			Options = PcreOptions.Compiled | (PcreOptions)( flags | ( ( selection & 1 ) != 0 ? 2u : 0u )
				| ( ( mode & 1 ) != 0 ? 0x80000u : 0u ) | ( ( mode & 2 ) != 0 ? 0x20000u : 0u )
				| ( ( mode & 4 ) != 0 ? 0x4000000u : 0u ) | ( ( mode & 8 ) != 0 ? 8u : 0u )
				| ( ( mode & 16 ) != 0 ? 0x80u : 0u ) | ( ( mode & 32 ) != 0 ? 0x8000000u : 0u ) ),
			ExtraCompileOptions = (PcreExtraCompileOptions)( ( selection & 2 ) != 0 ? 0x20 : 0 ),
			ParensLimit = 512
		} );
	private static PcreCompiledBytePattern Compile( byte[] source, PcreByteOptions options ) {
		var actual = PcreByteCompiler.Compile( source, options );
		Assert.True( actual.IsSuccess, $"{Encoding.UTF8.GetString( source )}: {actual.Diagnostic?.Message}" );
		return Assert.IsType<PcreCompiledBytePattern>( actual.Pattern );
	}
	private static void AssertLiteral( PcreRegex8Bit reference, byte[] subject, string spans, string mark ) {
		var match = reference.Match( subject );
		Assert.Equal( spans.Length > 0, match.Success );
		if ( !match.Success ) { return; }
		Assert.Equal( mark, Convert.ToHexString( match.Mark.ToArray() ) );
		var groups = spans.Split( ',' );
		Assert.Equal( groups.Length, match.Groups.Count );
		for ( var group = 0; group < groups.Length; group++ ) {
			var capture = match.Groups[group];
			Assert.Equal( groups[group], capture.Success ? $"{capture.Index}:{capture.Length}" : "-" );
		}
	}
	private static void Compare( PcreRegex8Bit reference, byte[] subject, int offset, PcreByteMatchResult actual, string context ) {
		var expected = reference.Match( subject, offset );
		Assert.True( actual.IsSuccess, $"{context}: {actual.Diagnostic?.Message}" );
		Assert.True( ( expected.Success ? expected.Index : -1 ) == ( actual.Match?.ByteIndex ?? -1 ), context );
		if ( !expected.Success ) { return; }
		Assert.Equal( expected.Length, actual.Match!.ByteLength );
		Assert.Equal( expected.Mark.ToArray(), actual.Match.MarkName.ToArray() );
		Assert.Equal( expected.Groups.Count, actual.Match.Captures.Count );
		for ( var group = 0; group < expected.Groups.Count; group++ ) {
			var capture = expected.Groups[group];
			Assert.Equal( capture.Success ? new PcreByteCapture( capture.Index, capture.Length ) : null, actual.Match.Captures[group] );
		}
	}
}
